import csv
from collections import defaultdict

streams={
 'F2_cool':'1213f3a8-c23d-55b5-8187-4712d49a82ae',
 'F2_heat':'b5c23ef3-f09b-5290-bfe0-1017cde1c4a5',
 'F2_temp':'baef86cb-2941-5d61-87b0-ffa91d79f23a',
 'F3_cool':'5b98cbc1-fd25-5d8c-a96e-c3de49819174',
 'F3_temp':'e0dd5f44-f050-5faa-a2a0-a3fcb6284ae8',
 'F4_cool':'22de734e-0a64-57ec-a6a5-f288ee06f947',
 'F4_temp':'14a08406-79a0-52ca-b8a1-8563259dc820',
}
data=defaultdict(dict)
with open(VALUES_CSV) as f:
    for r in csv.DictReader(f):
        if r['timeseries_id'] in streams:
            data[r['timeseries_id']][r['timestamp']]=float(r['value'])

def occ(ts):
    hh=int(ts[11:13])
    wd=ts[:10]
    import datetime
    d=datetime.date.fromisoformat(wd)
    wd=d.weekday()
    return wd<5 and 8<=hh<18  # weekday 8:00-17:00

def avg_by_period(sid, pred):
    vs=[v for t,v in data[sid].items() if pred(t)]
    return sum(vs)/len(vs), len(vs)

def period(ts):
    return 'BEFORE' if ts < '2018-06-15' else 'AFTER'

for key in ['F2_temp','F2_cool','F3_temp','F3_cool','F4_temp','F4_cool']:
    print('===',key)
    for p in ['BEFORE','AFTER']:
        for occb in [True, False]:
            m,n=avg_by_period(streams[key], lambda t: t[:10]!= '' and (period(t)==p) and (occ(t)==occb))
            label='occ' if occb else 'unocc'
            print(f'  {p} {label}: {m:.3f}  (n={n})')
